def head_ic(x, y, s, c):
    return f'<circle cx="{x}" cy="{y}" r="{s}" fill="{c}22"/><circle cx="{x}" cy="{y-s*.2}" r="{s*.38}" fill="{c}"/><path d="M{x-s*.65} {y+s*.75} Q{x} {y+s*.05} {x+s*.65} {y+s*.75} Z" fill="{c}"/>'
