# ================= Employee Attire: Work Polo And Layers (follow-on) =================
from uk5_attire import P as _P, A, B as PB, C as PC, D as PD, split2, strip, CHAR, KHAKI
def P(base, **k):
    k.setdefault("shoe", "athletic"); return _P(base, **k)
def shoe(x, y, s, c, stripe=None, cover=False, logo=False):
    if cover:
        o = f'<path d="M{x} {y+s*.55} Q{x} {y} {x+s*.6} {y+s*.1} Q{x+s*1.25} {y+s*.2} {x+s*1.3} {y+s*.62} Q{x+s*.65} {y+s*.8} {x} {y+s*.55} Z" fill="{c}"/>' + f'<path d="M{x+s*.05} {y+s*.52} Q{x+s*.65} {y+s*.66} {x+s*1.25} {y+s*.58}" stroke="#FFFFFF88" stroke-width="{s*.04}" fill="none"/>'
        if logo: o += mark(x + s * .85, y + s * .32, s * .1, c, "#FFFFFF")
        return o
    o = f'<path d="M{x} {y+s*.5} L{x} {y+s*.15} Q{x+s*.3} {y} {x+s*.55} {y+s*.18} Q{x+s*.9} {y+s*.3} {x+s*1.25} {y+s*.4} Q{x+s*1.32} {y+s*.5} {x+s*1.3} {y+s*.58} L{x} {y+s*.58} Z" fill="{c}"/>' + rect(x, y + s * .55, s * 1.3, s * .1, "#F2EFEA")
    if stripe: o += f'<path d="M{x+s*.35} {y+s*.5} L{x+s*.7} {y+s*.22}" stroke="{stripe}" stroke-width="{s*.08}" stroke-linecap="round"/>'
    return o
def shoepanel(**k):
    return rect(118, 30, 108, 236, "#FAF6EE") + shoe(132, 80, 60, k.pop("c", INK), **k) + shoe(132, 170, 60, k.get("c2", INK) if False else shoe_c[0], **k)
shoe_c = [INK]
def two(c, **k): return rect(118, 30, 108, 236, "#FAF6EE") + shoe(134, 84, 62, c, **k) + shoe(134, 174, 62, c, **k)
def cap(x, y, s, side):
    if not side:
        return f'<path d="M{x} {y+s*.6} Q{x} {y} {x+s*.6} {y} Q{x+s*1.2} {y} {x+s*1.2} {y+s*.6} Z" fill="#FFFFFF" stroke="{LINE}" stroke-width="2"/>' + f'<path d="M{x-s*.15} {y+s*.62} Q{x+s*.6} {y+s*.9} {x+s*1.35} {y+s*.62} Q{x+s*.6} {y+s*.72} {x-s*.15} {y+s*.62} Z" fill="#F2EFEA" stroke="{LINE}"/>' + mark(x + s * .6, y + s * .32, s * .14, "#FFFFFF", TERRA)
    return f'<path d="M{x} {y+s*.6} Q{x+s*.05} {y} {x+s*.6} {y} Q{x+s*1.1} {y+s*.05} {x+s*1.1} {y+s*.6} Z" fill="#FFFFFF" stroke="{LINE}" stroke-width="2"/>' + f'<path d="M{x+s*1.05} {y+s*.55} L{x+s*1.6} {y+s*.62} L{x+s*1.05} {y+s*.66} Z" fill="#F2EFEA" stroke="{LINE}"/>' + mark(x + s * .38, y + s * .38, s * .08, "#FFFFFF", TERRA)
def cappanel(side): return rect(138, 30, 88, 236, "#FAF6EE") + cap(148 if not side else 140, 100, 58 if not side else 50, side) + t(182, 190, "side view" if side else "front view", 7.5, MUTE, "hind", 400, "middle")
EA = []
def f(g, ask, x, y): EA.append((g, ask, x, y))
def AT(label, acc, body, foot=None): return card(label, acc, body + (chips(272, foot) if foot else ""))
