def namez(p, two):
    s = zoom(14, 30, 212, 236, p, 66, 3.4) + rect(110, 150, 104, 34 if two else 24, "#FFFFFF", LINE, 0, 1) + t(162, 166, "SAM", 11, INK, "khand", anchor="middle")
    if two: s += t(162, 178, "Certified Tech", 7.5, MUTE, "hind", 400, "middle")
    return s
