  opt("ea_covlogo", "With A Small Logo", "Members notice the care.", "bold", AT("Shoe Covers", TERRA, shot(14, 30, 100, 236, [P(PC, covers=TERRA)]) + two(TERRA, cover=True, logo=True), ["Branded"])),
